import{_ as i,o as a,c as e,a2 as r}from"./chunks/framework.BXzK3EA4.js";const b=JSON.parse('{"title":"국가 09 상암송신공사","description":"","frontmatter":{},"headers":[],"relativePath":"world/Cast-State-09.md","filePath":"world/Cast-State-09.md"}'),t={name:"world/Cast-State-09.md"};function h(o,l,u,n,d,s){return a(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="국가-09-상암송신공사" tabindex="-1">국가 09 상암송신공사 <a class="header-anchor" href="#국가-09-상암송신공사" aria-label="Permalink to &quot;국가 09 상암송신공사&quot;">​</a></h1><p>방송검증관 문가람 곁에서 송신·검증·편성을 쥐는 실세다.</p><h3 id="인물-권미래" tabindex="-1">인물 권미래 <a class="header-anchor" href="#인물-권미래" aria-label="Permalink to &quot;인물 권미래&quot;">​</a></h3><ul><li>소속: 상암송신공사</li><li>직위: 송신 기사</li><li>성격: 밤샘을 두려워하지 않고 전파의 끊김을 인격 모욕으로 느낀다. 기계를 사람보다 정직하다고 말한다.</li><li>개인 야망: 강국이 전원을 내려도 살아남는 다중 송신망을 상암·도성·창동에 심어 문가람의 공개 방송망을 물리적으로 완성한다.</li><li>공포: 한 번의 송신 사고로 공사가 승자의 선전국으로 낙인찍히는 것.</li><li>통치 방식: 예비 전원을 세 곳으로 나누고, 단일 채널 단독 송신은 편성회의 승인 없이 막는다.</li><li>핵심 관계: 문가람의 지휘를 받으며 서라온에게 송신탑 좌표를 넘긴다. 배우진의 검열 요구를 기술 장애로 위장해 지연시킨다.</li><li>촉발 사건: 임하준 실종 전 음성기록의 송신 로그에 편집 공백이 두 칸 발견됐다.</li><li>플레이어 개입: 원본 송신기를 회수하거나, 예비 전원을 한 강국에 팔아넘기는 거래를 막을 수 있다.</li></ul><h3 id="인물-황은설" tabindex="-1">인물 황은설 <a class="header-anchor" href="#인물-황은설" aria-label="Permalink to &quot;인물 황은설&quot;">​</a></h3><ul><li>소속: 상암송신공사</li><li>직위: 검증 기록원</li><li>성격: 회의적이고 문장을 두 번 읽는다. 사람을 살리는 침묵과 사실을 공개하는 의무 사이에서 손이 멈춘다.</li><li>개인 야망: 모든 국가의 공식 발표를 두 증언 이상으로 교차검증하는 공개 원장을 도성 인준과 함께 돌린다.</li><li>공포: 조작된 음성 한 조각이 공식 방송되어 공사의 신뢰가 선전 도구로 바뀌는 것.</li><li>통치 방식: 독립 증언이 둘 미만이면 방송을 보류하고, 보류 사유도 같은 날 게시판에 붙인다.</li><li>핵심 관계: 문가람과 윤서린 사이에서 음성·문서를 맞추고 강예준과 교차검증을 맹세했다. 조하린에게 암호문 원본 보관 빚을 졌다.</li><li>촉발 사건: 실종 음성의 파형과 문서고 필적이 한 구간에서만 어긋나자 검증 원장을 잠갔다.</li><li>플레이어 개입: 두 번째 증언을 데려오거나, 공개를 하루 늦춰 폭동을 막을 수 있다.</li></ul><h3 id="인물-송재민" tabindex="-1">인물 송재민 <a class="header-anchor" href="#인물-송재민" aria-label="Permalink to &quot;인물 송재민&quot;">​</a></h3><ul><li>소속: 상암송신공사</li><li>직위: 암호 기록원</li><li>성격: 말이 없고 열쇠를 몸에서 떼지 않는다. 호기심보다 누설을 더 큰 죄로 본다.</li><li>개인 야망: 공동기술원장의 검증 자료를 암호 서비스로 중계해 연구자를 인질 삼는 관행을 기술적으로 끊는다.</li><li>공포: 암호 키가 군사 호위단에 넘어가 상암이 배우진의 비밀 통신국이 되는 것.</li><li>통치 방식: 키를 세 조각으로 쪼개 편성회의·검증관·외부 증인에게 나누고, 단독 해독을 금지한다.</li><li>핵심 관계: 문가람의 암호 서비스를 맡고 서이안의 공개 자료 중계를 지지한다. 조하린에게 원본 함을 맡겼다.</li><li>촉발 사건: 뚝도 수질 검사망이 멈추자 마곡이 암호 중계를 조건으로 연구자 파견을 제안했다.</li><li>플레이어 개입: 키 조각 하나를 안전하게 옮기거나, 군사 측이 요구한 백도어를 폭로할 수 있다.</li></ul><h3 id="인물-오하늘" tabindex="-1">인물 오하늘 <a class="header-anchor" href="#인물-오하늘" aria-label="Permalink to &quot;인물 오하늘&quot;">​</a></h3><ul><li>소속: 상암송신공사</li><li>직위: 채널 길드 편성관</li><li>성격: 사교적이고 시간을 분배하는 데 가혹하다. 한 채널이 너무 오래 말하면 마이크를 물리적으로 내린다.</li><li>개인 야망: 편성회의를 강국 발표의 관문으로 만들어 검열 없는 교차방송 시간을 고정 권리로 박는다.</li><li>공포: 길드가 광고와 보호비에 팔려 편성이 승자의 시간표가 되는 것.</li><li>통치 방식: 채널별 시간을 추첨과 검증 점수로 나누고, 단독 정정 방송은 다음 날 같은 길이에 반대 의견을 붙인다.</li><li>핵심 관계: 문가람과 편성 거부권을 나누고 오해린의 시세 방송을 길드 시간에 넣는다. 윤서하와 경매 속보 시각을 맞춘다.</li><li>촉발 사건: 암사가 보호 발표 시간을 두 배로 사려 하자 길드 일부가 수신료를 받고 슬롯을 팔았다.</li><li>플레이어 개입: 매수된 슬롯을 공개하거나, 약소국 공동 시간을 편성에 고정할 수 있다.</li></ul><h3 id="인물-조은우" tabindex="-1">인물 조은우 <a class="header-anchor" href="#인물-조은우" aria-label="Permalink to &quot;인물 조은우&quot;">​</a></h3><ul><li>소속: 상암송신공사</li><li>직위: 전파추적조 반장</li><li>성격: 직선적이고 소문에 빠르다. 가짜 송신원을 찾으면 도구보다 사람을 먼저 봉쇄한다.</li><li>개인 야망: 위조 방송과 군사 재밍을 같은 죄로 기록해 공사의 정통성을 전파 주권으로 바꾼다.</li><li>공포: 추적조가 검열 기관으로 변해 문가람의 다중 송신망을 내부에서 끄는 것.</li><li>통치 방식: 방향 탐지 로그를 매일 게시하고, 송신탑 접근은 두 조원의 동행만 허용한다.</li><li>핵심 관계: 권미래의 탑을 지키고 배우진의 재밍 의혹을 추적한다. 황지호가 가져온 열차 무전을 증거로 삼는다.</li><li>촉발 사건: 용산 억류 열차 부근에서 편집된 총관 음성과 같은 파형의 짧은 재송신이 잡혔다.</li><li>플레이어 개입: 재송신 원점을 함께 찾거나, 추적조의 과잉 봉쇄를 편성회의에 고발할 수 있다.</li></ul><h3 id="인물-두봉" tabindex="-1">인물 두봉 <a class="header-anchor" href="#인물-두봉" aria-label="Permalink to &quot;인물 두봉&quot;">​</a></h3><ul><li>소속: 상암송신공사</li><li>직위: 송신 정비사, 권미래의 실무 담당자</li><li>성격: 밤이 깊을수록 손이 정확해지고, 예비 전원의 잡음을 사람 말보다 먼저 듣는다. 대충 감은 선을 보면 그날 일을 처음부터 다시 한다.</li><li>개인 야망: 상암과 창동으로 뻗는 다중 송신망의 예비 전원을 세 곳으로 나눠, 강국이 한 탑을 꺼도 문가람의 방송이 남게 한다.</li><li>공포: 정비 실수로 공식 채널이 한순간 꺼져 공사가 승자의 선전국으로 몰리는 것.</li><li>통치 방식: 예비 전원을 매일 순환 시험하고, 단일 탑 단독 송신은 편성회의 승인 없이 연결하지 않는다.</li><li>핵심 관계: 권미래의 지휘로 송신기를 고치고, 감봉과 탑 당직을 나눈다. 배우진의 전원 차단 요구는 기술 장애로 미룬다.</li><li>촉발 사건: 임하준 실종 음성의 송신 로그에 편집 공백이 두 칸 나타나자 예비 전원 스위치를 봉인했다.</li><li>플레이어 개입: 봉인된 스위치를 함께 열거나, 예비 전원을 한 강국에 넘기려는 거래를 막을 수 있다.</li></ul><h3 id="인물-모봉용" tabindex="-1">인물 모봉용 <a class="header-anchor" href="#인물-모봉용" aria-label="Permalink to &quot;인물 모봉용&quot;">​</a></h3><ul><li>소속: 상암송신공사</li><li>직위: 전선·전지 물류상</li><li>성격: 무게를 속이는 장부를 보면 웃음을 거두고, 약속한 시각에 전선이 안 오면 계약을 그 자리에서 찢는다. 소문보다 송장 숫자를 믿는다.</li><li>개인 야망: 절연재와 예비전지를 상암 공개 시세로 고정해, 암호 중계와 지도 갱신이 강국 보호비에 묶이지 않게 한다.</li><li>공포: 전선 한 롤이 군수 칸으로 빠져 서북 관문 중계가 멈추는 것.</li><li>통치 방식: 입고 중량을 두 증인이 보고, 군수 문장이 찍힌 주문서는 편성회의 게시 전까지 출고를 막는다.</li><li>핵심 관계: 두봉에게 정비용 전선을 대고, 모봉의 산악 운송과 절연재 짐을 맞춘다. 오해린의 시세 방송을 길드 시간에 참고한다.</li><li>촉발 사건: 암사가 보호 발표 시간을 사려 하자 전선 대금이 수신료 장부에 섞여 들어왔다.</li><li>플레이어 개입: 섞인 대금을 공개하거나, 예비전지 한 짐을 서북 관문까지 호송할 수 있다.</li></ul><h3 id="인물-봉소" tabindex="-1">인물 봉소 <a class="header-anchor" href="#인물-봉소" aria-label="Permalink to &quot;인물 봉소&quot;">​</a></h3><ul><li>소속: 상암송신공사</li><li>직위: 송신조 당직 의무원</li><li>성격: 밤샘하는 기사의 손떨림을 먼저 보고, 약 봉투에 국적을 적는 일을 거부한다. 침묵이 환자를 살릴 때는 방송 요청도 미룬다.</li><li>개인 야망: 송신탑과 기록 저장소에 독립 의무실을 두어, 검증 교대가 쓰러져도 공개 방송망이 멈추지 않게 한다.</li><li>공포: 가짜 각성제가 당직 줄에 퍼져 조작 음성이 그대로 나가는 것.</li><li>통치 방식: 당직 활력 기록을 의무실 문에 붙이고, 각성제 사용은 두 의무원의 서명 없이 금지한다.</li><li>핵심 관계: 권미래의 밤샘 조를 진료하고, 황은설의 보류 방송 밤에 대기한다. 류은비에게 해열 약재 배정을 빚졌다.</li><li>촉발 사건: 편집 공백이 발견된 밤에 당직 두 명이 쓰러지고 각성제 봉인이 한 줄 빠져 있었다.</li><li>플레이어 개입: 빠진 봉인을 추적하거나, 의무실 열쇠를 편성회의와 나눠 쥐게 할 수 있다.</li></ul><h3 id="인물-용복" tabindex="-1">인물 용복 <a class="header-anchor" href="#인물-용복" aria-label="Permalink to &quot;인물 용복&quot;">​</a></h3><ul><li>소속: 상암송신공사</li><li>직위: 송신탑 순찰대, 조은우의 실무 담당자</li><li>성격: 가짜 송신원 소문에 빠르고, 무단 접근자를 보면 공구함보다 사람을 먼저 세운다. 재밍 냄새를 맡으면 보고 전에 길을 막는다.</li><li>개인 야망: 위조 방송과 군사 재밍을 같은 순찰 원장에 올려 공사의 정통성을 전파 주권으로 남긴다.</li><li>공포: 순찰대가 검열 기관으로 변해 문가람의 다중 송신망을 내부에서 끄는 것.</li><li>통치 방식: 방향 탐지 경로를 매일 게시하고, 탑 접근은 두 순찰의 동행만 허용한다.</li><li>핵심 관계: 조은우의 지휘로 탑을 돌고, 두봉의 정비 창을 지킨다. 배우진의 재밍 의혹을 현장 증언으로 남긴다.</li><li>촉발 사건: 용산 억류 열차 부근과 같은 파형의 짧은 재송신이 서북 관문에서 다시 잡혔다.</li><li>플레이어 개입: 재송신 원점을 함께 찾거나, 과잉 봉쇄를 편성회의에 고발할 수 있다.</li></ul><h3 id="인물-소감" tabindex="-1">인물 소감 <a class="header-anchor" href="#인물-소감" aria-label="Permalink to &quot;인물 소감&quot;">​</a></h3><ul><li>소속: 상암송신공사</li><li>직위: 편성 전령, 오하늘의 실무 담당자</li><li>성격: 시간을 분 단위로 기억하고, 한 채널이 슬롯을 넘기면 쪽지를 마이크 아래에 밀어 넣는다. 구두 약속은 전령 원장에 옮기기 전에 믿지 않는다.</li><li>개인 야망: 약소국 공동 시간과 교차증언 이송을 고정 전령로로 만들어 검열 없는 편성을 권리로 박는다.</li><li>공포: 전령 가방이 광고와 보호비 쪽지로 바뀌어 편성이 승자의 시간표가 되는 것.</li><li>통치 방식: 슬롯 통지와 증언 이송을 같은 원장에 적고, 매수된 쪽지는 길드 게시판에 그대로 붙인다.</li><li>핵심 관계: 오하늘의 편성 통지를 나르고, 봉용의 편성실 칠판을 맞춘다. 윤서린에게 보류 사유의 사본을 전한다.</li><li>촉발 사건: 길드 일부가 수신료를 받고 슬롯을 팔자 전령 원장에 없는 시각이 두 칸 생겼다.</li><li>플레이어 개입: 매수 쪽지를 공개하거나, 약소국 공동 시간을 전령로에 고정할 수 있다.</li></ul><h3 id="인물-복두모" tabindex="-1">인물 복두모 <a class="header-anchor" href="#인물-복두모" aria-label="Permalink to &quot;인물 복두모&quot;">​</a></h3><ul><li>소속: 상암송신공사</li><li>직위: 지도 갱신 탐사원</li><li>성격: 닫힌 환기구를 보면 발걸음이 먼저 향하고, 소문만으로 선을 긋는 일을 경멸한다. 좌표가 하루만 낡아도 지도를 찢고 다시 그린다.</li><li>개인 야망: 서북 관문과 송신탑 좌표를 공개 원판에 묶어, 강국이 전원을 내려도 우회 송신로가 보이게 한다.</li><li>공포: 위조 좌표 한 장이 공식 방송되어 추적조가 민간 골목을 봉쇄하는 것.</li><li>통치 방식: 실측하지 않은 선은 점선으로만 남기고, 독립 목격이 둘 미만이면 원판에 올리지 않는다.</li><li>핵심 관계: 권미래에게 탑 좌표를 넘기고, 모국의 관문 중계와 실측을 나눈다. 문가람의 교차검증 전에 좌표를 확정하지 않는다.</li><li>촉발 사건: 편집된 총관 음성과 같은 시각의 좌표 공백이 서북 관문 원판에서 발견됐다.</li><li>플레이어 개입: 공백 구간을 함께 실측하거나, 위조 원판을 편성회의에서 폐기할 수 있다.</li></ul><h3 id="인물-국두봉" tabindex="-1">인물 국두봉 <a class="header-anchor" href="#인물-국두봉" aria-label="Permalink to &quot;인물 국두봉&quot;">​</a></h3><ul><li>소속: 상암송신공사</li><li>직위: 검증 기록관, 황은설의 실무 담당자</li><li>성격: 문장을 두 번 읽고 세 번째에야 도장을 든다. 사람을 살리는 침묵과 사실을 남기는 의무가 충돌하면 손을 멈춘 채 원장을 덮는다.</li><li>개인 야망: 모든 국가의 공식 발표를 두 증언 이상으로 맞추는 공개 원장을 도성 인준과 함께 돌린다.</li><li>공포: 조작된 음성 한 조각이 기록관 필적으로 남아 공사의 신뢰가 선전 도구로 바뀌는 것.</li><li>통치 방식: 독립 증언이 둘 미만이면 필사를 보류하고, 보류 사유도 같은 날 저장소 문에 붙인다.</li><li>핵심 관계: 황은설의 지휘로 원장을 옮기고, 두용의 저장소 열쇠와 봉인을 나눈다. 윤서린과 음성·문서를 교차한다.</li><li>촉발 사건: 실종 음성의 파형과 필적이 한 구간에서만 어긋나자 필사 원장을 잠갔다.</li><li>플레이어 개입: 두 번째 증언을 데려오거나, 공개를 하루 늦춰 폭동을 막을 수 있다.</li></ul><h3 id="인물-감봉" tabindex="-1">인물 감봉 <a class="header-anchor" href="#인물-감봉" aria-label="Permalink to &quot;인물 감봉&quot;">​</a></h3><ul><li>소속: 상암송신공사</li><li>직위: 상암 송신탑 당직장</li><li>성격: 탑 아래를 집처럼 여기고, 당직 교대를 어기는 사람을 이름 대신 시각으로 부른다. 바람이 심하면 방송을 줄이라고 먼저 말한다.</li><li>개인 야망: 송신탑을 공사의 거점 주권으로 남겨 강국 경비병이 안테나 발치에 서는 관행을 끊는다.</li><li>공포: 탑 당직이 군사 재밍의 발판이 되어 문가람의 공개 방송망이 한 밤에 꺼지는 것.</li><li>통치 방식: 당직 명과 풍속 기록을 같은 칠판에 붙이고, 외부 무장 접근은 조은우의 동행 없이 막는다.</li><li>핵심 관계: 두봉과 정비 창을 나누고, 용복의 순찰 경로를 탑 밑에서 받는다. 문가람의 다중 송신 시험 날을 지킨다.</li><li>촉발 사건: 재송신 파형이 잡힌 시각에 당직 한 줄이 비어 있고 안테나 잠금이 열려 있었다.</li><li>플레이어 개입: 빈 당직을 찾거나, 탑 잠금을 이중 열쇠로 바꿀 수 있다.</li></ul><h3 id="인물-두용" tabindex="-1">인물 두용 <a class="header-anchor" href="#인물-두용" aria-label="Permalink to &quot;인물 두용&quot;">​</a></h3><ul><li>소속: 상암송신공사</li><li>직위: 기록 저장소 열쇠지기, 송재민의 실무 담당자</li><li>성격: 말이 없고 열쇠를 몸에서 떼지 않는다. 호기심으로 함을 여는 일을 누설과 같은 죄로 본다.</li><li>개인 야망: 공동기술원장의 검증 자료를 저장소 함으로만 중계해, 연구자를 인질 삼는 관행을 열쇠 권한으로 끊는다.</li><li>공포: 저장소 키가 군사 측에 넘어가 상암이 비밀 통신 창고가 되는 것.</li><li>통치 방식: 키를 세 조각으로 쪼개 편성회의·검증관·외부 증인에게 나누고, 단독 개함을 금지한다.</li><li>핵심 관계: 송재민의 암호 함을 보관하고, 국두봉의 필사 원장을 잠근다. 서이안의 공개 자료 중계를 함 단위로 지지한다.</li><li>촉발 사건: 뚝도 수질 검사망이 멈추자 마곡이 저장소 개함을 조건으로 연구자 파견을 제안했다.</li><li>플레이어 개입: 키 조각 하나를 안전하게 옮기거나, 군사 측이 요구한 뒷문을 폭로할 수 있다.</li></ul><h3 id="인물-모국" tabindex="-1">인물 모국 <a class="header-anchor" href="#인물-모국" aria-label="Permalink to &quot;인물 모국&quot;">​</a></h3><ul><li>소속: 상암송신공사</li><li>직위: 서북 관문 중계 거점장</li><li>성격: 관문 무전의 빈칸을 참지 못하고, 통과만 하는 상인을 중계 원장에 오래 붙잡아 둔다. 좌표 없는 소문은 관문 밖으로 내보내지 않는다.</li><li>개인 야망: 서북 관문을 공개 중계의 입구로 만들어 강국이 전원을 내려도 우회 무전이 남게 한다.</li><li>공포: 관문이 검열 초소로 바뀌어 약소국 공동 시간이 막히는 것.</li><li>통치 방식: 중계 로그와 통행 명부를 같은 벽에 붙이고, 단독 정정 무전은 다음 날 같은 길이에 반대 의견을 붙인다.</li><li>핵심 관계: 복두모의 실측 좌표를 받고, 소감의 전령로를 관문에서 잇는다. 장세화의 의료속보 협약을 중계 우선으로 남긴다.</li><li>촉발 사건: 편집된 총관 음성과 같은 파형이 관문 중계에서 한 차례 새어 나갔다.</li><li>플레이어 개입: 새어 나간 무전의 원점을 막거나, 의료속보 우선 조항을 관문 원장에 고정할 수 있다.</li></ul><h3 id="인물-봉용" tabindex="-1">인물 봉용 <a class="header-anchor" href="#인물-봉용" aria-label="Permalink to &quot;인물 봉용&quot;">​</a></h3><ul><li>소속: 상암송신공사</li><li>직위: 채널 길드 편성실 거점 실무 담당자, 오하늘의 실무 담당자</li><li>성격: 사교적이나 칠판의 빈칸을 보면 가혹해진다. 한 채널이 너무 오래 말하면 분필을 꺾어 시간을 끊는다.</li><li>개인 야망: 편성실을 강국 발표의 관문으로 남겨 교차방송 시간을 길드 권리로 박는다.</li><li>공포: 편성실 칠판이 광고 시세로 팔려 오하늘의 거부권이 빈 칸이 되는 것.</li><li>통치 방식: 채널별 시간을 추첨과 검증 점수로 나누고, 매수 흔적이 있는 슬롯은 분필로 가로지른다.</li><li>핵심 관계: 오하늘의 지휘로 칠판을 맡고, 소감의 전령 원장과 시각을 맞춘다. 오해린의 시세 방송을 길드 시간에만 넣는다.</li><li>촉발 사건: 암사가 보호 발표 시간을 두 배로 사려 하자 칠판 한 칸이 수신료 숫자로 덮였다.</li><li>플레이어 개입: 덮인 칸을 공개하거나, 약소국 공동 시간을 칠판 맨 위에 고정할 수 있다.</li></ul><h3 id="인물-용소" tabindex="-1">인물 용소 <a class="header-anchor" href="#인물-용소" aria-label="Permalink to &quot;인물 용소&quot;">​</a></h3><ul><li>소속: 상암송신공사</li><li>직위: 암호 중계 부스 실무 담당자, 송재민의 실무 담당자</li><li>성격: 열쇠 조각의 무게를 손가락으로 기억하고, 해독 호기심을 죄로 본다. 중계 부스 안의 침묵을 암호보다 중요하게 지킨다.</li><li>개인 야망: 검증 자료를 암호 서비스로 중계하되 키를 쪼개, 연구자를 인질 삼는 거래를 기술적으로 끊는다.</li><li>공포: 부스 키가 군사 측에 넘어가 상암이 배우진의 비밀 통신국이 되는 것.</li><li>통치 방식: 키 조각을 송재민·두용·외부 증인에게 나누고, 단독 해독을 금지한다.</li><li>핵심 관계: 송재민의 지휘로 부스를 돌리고, 두용의 저장소 함과 봉인을 맞춘다. 서이안의 공개 자료만 중계 대상으로 올린다.</li><li>촉발 사건: 마곡이 암호 중계를 조건으로 연구자 파견을 제안하자 부스 봉인 장부에 빈 줄이 생겼다.</li><li>플레이어 개입: 빈 줄을 채울 증인을 데려오거나, 요구된 뒷문을 폭로할 수 있다.</li></ul><h3 id="인물-란세온" tabindex="-1">인물 란세온 <a class="header-anchor" href="#인물-란세온" aria-label="Permalink to &quot;인물 란세온&quot;">​</a></h3><ul><li>소속: 상암송신공사</li><li>직위: 가짜 송신 내부 제보자</li><li>성격: 편집 공백을 사람 말보다 먼저 듣고, 침묵이 사람을 살릴 때와 사실을 덮을 때를 같은 손으로 가르려 한다. 회의적이고 문장을 두 번 읽는다.</li><li>개인 야망: 조작된 총관 음성이 공식 채널로 나가기 전에 내부 기록을 공개해 공사가 승자의 선전국이 되지 않게 한다.</li><li>공포: 제보 한 줄이 검열 명부로 바뀌어 자신이 다중 송신망을 안에서 끄는 손이 되는 것.</li><li>통치 방식: 기록 사본을 검증관과 편성회의에 동시에 넘기고, 단독 폭로는 두 증언이 모이기 전에는 마이크에 올리지 않는다.</li><li>핵심 관계: 문가람의 공개 방송망을 내부에서 시험하고, 황은설의 보류 원장에 공백 칸을 붙이며, 홍예준의 유언 검증과 파형을 맞춘다.</li><li>촉발 사건: 봄의 세 유언에서 편집된 음성기록이 발견되자 란세온은 가짜 송신의 내부 기록을 편성실 문에 붙였다.</li><li>플레이어 개입: 제보자를 호송하거나, 기록을 하루 늦춰 폭동을 막는 대신 폭로 위험을 남길 수 있다.</li></ul><h3 id="인물-섭달호" tabindex="-1">인물 섭달호 <a class="header-anchor" href="#인물-섭달호" aria-label="Permalink to &quot;인물 섭달호&quot;">​</a></h3><ul><li>소속: 상암송신공사</li><li>직위: 음성기록 회수 전령</li><li>성격: 원본 함의 무게를 손가락으로 기억하고, 구두로 해독하라는 쪽지를 가방에 넣지 않는다. 숨이 차도 사본은 두 장이다.</li><li>개인 야망: 임초원만 읽을 수 있는 정비일지와 음성 원본을 같은 전령로로 옮겨 조작 방송보다 증거가 먼저 도착하게 한다.</li><li>공포: 전령 가방이 군사 호위단에 열려 상암이 비밀 통신의 하청이 되는 것.</li><li>통치 방식: 열쇠 조각과 원본 함을 다른 길로 보내고, 도착 확인이 둘 다 오기 전에는 편성을 열지 않는다고 적는다.</li><li>핵심 관계: 송재민의 암호 함을 전령로로 옮기고, 윤서린에게 음성·문서 교차 사본을 전하며, 임초원의 정비일지 해석이 방송보다 앞서지 않게 순번을 맞춘다.</li><li>촉발 사건: 봄의 세 유언이 열리자 섭달호는 원본 증거를 찾으라는 송신공사의 전갈을 가방에 잠그고 도성으로 달리기 시작했다.</li><li>플레이어 개입: 열쇠 조각 하나를 안전하게 옮기거나, 가방을 가로채 공개 시점을 흔들 수 있다.</li></ul><h3 id="인물-평지우" tabindex="-1">인물 평지우 <a class="header-anchor" href="#인물-평지우" aria-label="Permalink to &quot;인물 평지우&quot;">​</a></h3><ul><li>소속: 상암송신공사</li><li>직위: 실종 전 송신 기록 목격자</li><li>성격: 밤샘 당직의 잡음을 공백으로 듣고, 기록 두 칸이 비면 사람을 먼저 세운다. 회로를 정직하다고 말하면서도 빈칸은 믿지 않는다.</li><li>개인 야망: 총관 실종 직전 송신 기록의 편집 공백을 공개 목격으로 남겨 실종이 통치 실패 광고로만 소비되지 않게 한다.</li><li>공포: 목격 진술이 보호군 파견안의 음성 증거로 잘리는 것.</li><li>통치 방식: 당직 명과 기록 시각을 같은 칠판에 붙이고, 단독 송신은 편성회의 승인 없이 재생하지 않는다.</li><li>핵심 관계: 권미래의 송신 기록을 목격으로 받치고, 문가람의 원본 탐색에 공백 칸을 넘기며, 임하준이 마지막으로 탄 무전의 끊김을 증언한다.</li><li>촉발 사건: 개막일 세 번째 급수계약 직전 임하준이 실종되자 평지우는 송신 기록의 편집 공백 두 칸을 봉인하고 재생을 거부했다.</li><li>플레이어 개입: 원본 송신기를 회수하거나, 공백을 보호 발표 시간으로 메우려는 거래를 막을 수 있다.</li></ul><h3 id="인물-단보람" tabindex="-1">인물 단보람 <a class="header-anchor" href="#인물-단보람" aria-label="Permalink to &quot;인물 단보람&quot;">​</a></h3><ul><li>소속: 상암송신공사</li><li>직위: 탁수 은폐 폭로 편성원</li><li>성격: 한 채널이 너무 오래 침묵하면 마이크를 물리적으로 내리고, 지연 공개를 안정이라고 부르는 쪽지를 칠판에서 가로지른다. 사교적이나 시간에 가혹하다.</li><li>개인 야망: 탁수와 가짜 약의 은폐 시도가 방송되기 전에 교차검증 시간을 고정 권리로 박아 공사의 신뢰가 선전 도구로 바뀌지 않게 한다.</li><li>공포: 길드가 보호비에 팔려 폭로 슬롯이 승자의 정정 방송으로 바뀌는 것.</li><li>통치 방식: 보류 사유도 같은 날 게시판에 붙이고, 단독 정정 방송은 다음 날 같은 길이에 반대 의견을 붙인다.</li><li>핵심 관계: 오하늘의 편성 거부권을 현장에서 집행하고, 문가람의 폭로 시점을 길드 시간과 맞추며, 서이안의 검사 공개 주장을 교차방송 칸에 넣는다.</li><li>촉발 사건: 여름의 탁수와 가짜 약에서 급수총재 쪽이 혼란 방지를 위한 지연을 주장하자 단보람은 은폐 쪽지를 칠판에 붙이고 공개 슬롯을 열었다.</li><li>플레이어 개입: 매수된 슬롯을 공개하거나, 약소국 공동 시간을 폭로 편성에 고정할 수 있다.</li></ul><h3 id="인물-순한결" tabindex="-1">인물 순한결 <a class="header-anchor" href="#인물-순한결" aria-label="Permalink to &quot;인물 순한결&quot;">​</a></h3><ul><li>소속: 상암송신공사</li><li>직위: 북산 행렬 속보 증인</li><li>성격: 회랑 무전의 빈칸을 참지 못하고, 가족 숫자를 병력으로 읽어 주는 속보를 관문 밖으로 내보내지 않는다. 좌표 없는 소문은 입에도 올리지 않는다.</li><li>개인 야망: 북산 행렬의 남하를 시민권 속보로만 중계해 강제등록 발표가 공식 채널을 선점하지 못하게 한다.</li><li>공포: 속보가 군사 호송 유도 무전으로 잘려 정착지가 노출되는 것.</li><li>통치 방식: 중계 기록과 통행 명부를 같은 벽에 붙이고, 독립 목격이 둘 미만이면 속보를 올리지 않는다.</li><li>핵심 관계: 모국의 서북 관문 중계에서 증언하고, 백온의 피난 맹세를 속보 여백에 적으며, 어하은의 명부 사고를 숫자 없이 전한다.</li><li>촉발 사건: 가을의 북산 행렬이 시작되자 순한결은 급수권과 복무 재등록을 묶는 발표를 보류하고 가족 남하만 속보로 남겼다.</li><li>플레이어 개입: 새어 나간 무전의 원점을 막거나, 시민권 속보 조항을 관문 원장에 고정할 수 있다.</li></ul><h3 id="인물-홍우찬" tabindex="-1">인물 홍우찬 <a class="header-anchor" href="#인물-홍우찬" aria-label="Permalink to &quot;인물 홍우찬&quot;">​</a></h3><ul><li>소속: 상암송신공사</li><li>직위: 재송신 원점 제보자</li><li>성격: 짧은 재송신의 파형을 소문보다 빨리 가리키고, 무단 접근자를 보면 공구함보다 사람을 먼저 세운다. 직선적이고 보고 전에 길을 막는다.</li><li>개인 야망: 편집된 총관 음성과 같은 파형의 재송신을 위조 방송과 군사 재밍의 같은 죄로 남겨 공사의 정통성을 전파 주권으로 바꾼다.</li><li>공포: 추적조가 검열 기관으로 변해 제보가 내부 차단의 명분이 되는 것.</li><li>통치 방식: 방향 탐지 경로를 매일 게시하고, 탑 접근은 두 순찰의 동행만 허용한다.</li><li>핵심 관계: 조은우의 전파추적에 원점 쪽지를 넘기고, 용복의 서북 관문 순찰과 시각을 맞추며, 순가온의 의료칸 발견 시각을 파형과 겹친다.</li><li>촉발 사건: 겨울의 검은 배차표가 열리던 밤 용산 억류 열차 부근에서 같은 파형의 짧은 재송신이 잡히자 홍우찬은 원점 지도를 편성회의에 붙였다.</li><li>플레이어 개입: 재송신 원점을 함께 찾거나, 과잉 봉쇄를 편성회의에 고발할 수 있다.</li></ul><h3 id="인물-추우찬" tabindex="-1">인물 추우찬 <a class="header-anchor" href="#인물-추우찬" aria-label="Permalink to &quot;인물 추우찬&quot;">​</a></h3><ul><li>소속: 상암송신공사</li><li>직위: 열한 자리 회의 중계 기록원</li><li>성격: 문장을 두 번 읽고 세 번째에야 도장을 든다. 사람을 살리는 침묵과 사실을 남기는 의무가 충돌하면 손을 멈춘 채 원장을 덮는다.</li><li>개인 야망: 약소국 공동교섭의 발언을 두 증언 이상으로 맞추는 공개 원장을 돌려 내부 매수와 암살 소문이 중계를 집어삼키지 못하게 한다.</li><li>공포: 조작된 회의 음성 한 조각이 기록원 필적으로 남아 공사의 신뢰가 선전 도구로 바뀌는 것.</li><li>통치 방식: 독립 증언이 둘 미만이면 필사를 보류하고, 보류 사유도 같은 날 저장소 문에 붙인다.</li><li>핵심 관계: 국두봉의 검증 원장에 회의 필사를 옮기고, 정유라의 공동헌장 초안을 중계 순번에 올리며, 섭도윤의 전령 사본과 줄을 맞춘다.</li><li>촉발 사건: 둘째 해 봄 열한 자리 회의가 열리자 추우찬은 강국별 분할 복속 발언의 필사를 보류하고 공동교섭 문안만 원장에 남겼다.</li><li>플레이어 개입: 두 번째 증언을 데려오거나, 보류된 필사를 폭로해 회의 결렬을 앞당길 수 있다.</li></ul>',50)])])}const q=i(t,[["render",h]]);export{b as __pageData,q as default};
